    @inline(__always)
    private func checkSlide1UpConstantA(_ value: Lane) {
        let mismatches = Mismatches("slide1Up with a repeating \(hex(value))")
        mismatches.check(
            H.repeating(value),
            H(raw: HighwayReference.repeatingI8(value)),
            "repeating"
        )
        mismatches.check(
            H.slide1Up(H.repeating(value)),
            H(raw: HighwayReference.slide1UpI8(H.repeating(value).raw)),
            ""
        )
        mismatches.record()
    }

